arguments.newString:
def _safe_float(val: str | None, default: float | None = None) -> float | None:
    """Parse a CREDIT_SUMMARY value, returning the default for special/missing values."""
    if val is None or val == "" or val == "N/A":
        return default
    try:
        v = float(val)
        # -3 / -4 / -5 are reserved "no data" codes, never real amounts.
        if v in (-3.0, -4.0, -5.0):
            return default
        return v
    except (ValueError, TypeError):
        return default

